import { SessionLauncherPreviewQuery } from '../__generated__/SessionLauncherPreviewQuery.graphql';
import { App } from '../app-shim';
// FRONTIER (ticket 17 / ticket 34): `Form.useFormInstance` / `Form.useWatch`
// keep reading the antd form engine (locked SHIM decision).
import { Form } from '../form-engine';
import { getImageFullName } from '../helper';
import { getSessionTypeLabel } from '../helper/sessionTypeLabel';
import {
  useBackendAIImageMetaData,
  useSuspendedBackendaiClient,
} from '../hooks';
import { useCurrentProjectValue } from '../hooks/useCurrentProject';
import { useMountableStorageHosts } from '../hooks/useMountableStorageHosts';
import type {
  SessionLauncherFormValue,
  SessionLauncherStepKey,
} from '../pages/SessionLauncherPage';
import { useFolderExplorerOpener } from './FolderExplorerOpener';
import { ImageMetaDivider, ImageTagTokens } from './ImageTags';
import { PortToken } from './PortSelectFormItem';
import { ResourceNumbersOfSession } from './ResourceNumbersOfSession';
import SourceCodeView from './SourceCodeView';
import { Banner } from '@lablup/ui-common/Banner';
import { Button } from '@lablup/ui-common/Button';
import { Card } from '@lablup/ui-common/Card';
import { Heading } from '@lablup/ui-common/Heading';
import { MetadataListItem } from '@lablup/ui-common/MetadataList';
import { Text } from '@lablup/ui-common/Text';
import { Token } from '@lablup/ui-common/Token';
import {
  BAICard,
  BAIFlex,
  BAIImageMetaIcon,
  BAILink,
  BAIMetadataList,
  BAITable,
  BAIVFolderIdenticon,
  BAIText,
  imageNodeTagFacts,
  filterOutEmpty,
  mountableVFolderScope,
  resolveVFolderMounts,
  useSuspendedAutoMountedVFolders,
} from 'backend.ai-ui';
import dayjs from 'dayjs';
import * as _ from 'lodash-es';
import { useTranslation } from 'react-i18next';
import { graphql, useLazyLoadQuery } from 'react-relay';

// The batch timeout select's unit values (SessionLauncherPage).
const BATCH_TIMEOUT_UNIT_LABEL_KEYS: Record<string, string> = {
  s: 'time.Sec',
  m: 'time.Min',
  h: 'time.Hour',
  d: 'time.Day',
  w: 'time.Week',
};

/**
 * The review step's image row. A manually typed image has no parts to
 * decompose, so it stays a copyable code string; a picked image is a legacy
 * `Image` form value with no fragment, so the row is drawn here (ADR 0005).
 */
const SessionLauncherImageRow: React.FC = () => {
  'use memo';
  const form = Form.useFormInstance<SessionLauncherFormValue>();
  const [, { tagAlias }] = useBackendAIImageMetaData();

  const environments = form.getFieldValue('environments');
  const image = environments?.image;

  if (environments?.manual) {
    return (
      <BAIFlex direction="row" align="center" gap="xs" wrap="nowrap">
        <BAIImageMetaIcon image={environments.manual} />
        <BAIText code copyable>
          {environments.manual}
        </BAIText>
      </BAIFlex>
    );
  }

  const fullName = getImageFullName(image) || environments?.version;
  const facts = imageNodeTagFacts(image?.tags, image?.labels, tagAlias);

  return (
    <BAIFlex direction="row" wrap="wrap" gap="xxs">
      <BAIImageMetaIcon image={fullName} />
      <Text>{tagAlias(image?.base_image_name)}</Text>
      <ImageMetaDivider />
      <Text>{image?.version}</Text>
      <ImageMetaDivider />
      <Text>{image?.architecture}</Text>
      {!_.isEmpty(facts) ? (
        <>
          <ImageMetaDivider />
          <ImageTagTokens facts={facts} />
        </>
      ) : null}
      <BAIText copyable={{ text: fullName }} />
    </BAIFlex>
  );
};

const SessionLauncherPreview: React.FC<{
  onClickEditStep: (stepKey: SessionLauncherStepKey) => void;
  currentProjectId: string;
}> = ({ onClickEditStep, currentProjectId }) => {
  const app = App.useApp();
  const { t } = useTranslation();
  const form = Form.useFormInstance<SessionLauncherFormValue>();
  const baiClient = useSuspendedBackendaiClient();
  const sessionType = Form.useWatch('sessionType', { form, preserve: true });
  const currentProject = useCurrentProjectValue();
  const mountableHosts = useMountableStorageHosts(currentProjectId);
  // `allocationPreset` holds the preset's id; the store already has the
  // list from `ResourcePresetSelect`, so this resolves without a request.
  const { resource_presets } = useLazyLoadQuery<SessionLauncherPreviewQuery>(
    graphql`
      query SessionLauncherPreviewQuery {
        resource_presets {
          id
          name
        }
      }
    `,
    {},
    { fetchPolicy: 'store-or-network' },
  );
  const allocationPreset = form.getFieldValue('allocationPreset');
  // Names how the resources were allocated, ahead of the numbers.
  const allocationMethodLabel = !allocationPreset
    ? undefined
    : allocationPreset === 'custom'
      ? t('session.launcher.CustomAllocation')
      : allocationPreset === 'minimum-required'
        ? t('session.launcher.MiniumAllocation')
        : `${t('resourcePreset.ResourcePreset')}: ${
            _.find(
              resource_presets,
              (preset) => preset?.id === allocationPreset,
            )?.name ?? allocationPreset
          }`;
  const { autoMountedFolders } = useSuspendedAutoMountedVFolders({
    scope: mountableVFolderScope(baiClient.user_uuid, currentProjectId),
    mountableHosts,
  });
  const { generateFolderPath } = useFolderExplorerOpener();

  const mountRows = resolveVFolderMounts(form.getFieldValue('vfolderMounts'));

  return (
    <>
      {form.getFieldValue('bootstrap_script') && (
        <Banner
          role="status"
          status="info"
          title={t('session.launcher.UsingBootstrapScriptInfo')}
          endContent={
            <Button
              size="sm"
              variant="ghost"
              label={t('notification.SeeDetail')}
              onClick={() => {
                app.modal.info({
                  title: t('session.launcher.BootstrapScriptDetail'),
                  content: (
                    <BAIFlex direction="column" align="start">
                      <Text as="p" display="block">
                        {t('userSettings.BootstrapScriptDescription')}
                      </Text>
                      <SourceCodeView language={'shell'}>
                        {form.getFieldValue('bootstrap_script')}
                      </SourceCodeView>
                    </BAIFlex>
                  ),
                  width: 800,
                });
              }}
            />
          }
        />
      )}
      <BAICard
        title={t('session.launcher.SessionType')}
        showDivider
        size="small"
        status={
          form.getFieldError('sessionName').length > 0 ||
          form.getFieldError(['batch', 'command']).length > 0 ||
          form.getFieldError(['batch', 'scheduleDate']).length > 0
            ? 'error'
            : undefined
        }
        extraButtonTitle={t('button.Edit')}
        onClickExtraButton={() => {
          onClickEditStep('sessionType');
        }}
      >
        <BAIMetadataList columns="single">
          <MetadataListItem label={t('session.SessionType')}>
            {getSessionTypeLabel(t, form.getFieldValue('sessionType'))}
          </MetadataListItem>
          {!_.isEmpty(form.getFieldValue('sessionName')) && (
            <MetadataListItem label={t('session.launcher.SessionName')}>
              {form.getFieldValue('sessionName')}
            </MetadataListItem>
          )}
          {sessionType === 'batch' && (
            <>
              <MetadataListItem label={t('session.launcher.StartUpCommand')}>
                {form.getFieldValue(['batch', 'command']) ? (
                  <SourceCodeView language="shell">
                    {form.getFieldValue(['batch', 'command'])}
                  </SourceCodeView>
                ) : (
                  <Text color="secondary">{t('general.None')}</Text>
                )}
              </MetadataListItem>
              <MetadataListItem label={t('session.launcher.SessionStartTime')}>
                {form.getFieldValue(['batch', 'scheduleDate']) ? (
                  dayjs(form.getFieldValue(['batch', 'scheduleDate'])).format(
                    'LLL (Z)',
                  )
                ) : (
                  <Text color="secondary">{t('general.None')}</Text>
                )}
              </MetadataListItem>
              <MetadataListItem
                label={t('session.launcher.BatchJobTimeoutDuration')}
              >
                {form.getFieldValue(['batch', 'timeout']) ? (
                  <Text>
                    {`${form.getFieldValue(['batch', 'timeout'])} ${t(
                      BATCH_TIMEOUT_UNIT_LABEL_KEYS[
                        form.getFieldValue(['batch', 'timeoutUnit']) ?? 's'
                      ] ?? 'time.Sec',
                    )}`}
                  </Text>
                ) : (
                  <Text color="secondary">{t('general.None')}</Text>
                )}
              </MetadataListItem>
            </>
          )}
        </BAIMetadataList>
      </BAICard>
      <BAICard
        title={t('session.launcher.Environments')}
        showDivider
        size="small"
        status={
          _.some(
            form.getFieldValue(
              'envvars',
            ) as SessionLauncherFormValue['envvars'],
            (_v, idx) => {
              return (
                form.getFieldError(['envvars', idx, 'variable']).length > 0 ||
                form.getFieldError(['envvars', idx, 'value']).length > 0
              );
            },
          )
            ? 'error'
            : undefined
        }
        extraButtonTitle={t('button.Edit')}
        onClickExtraButton={() => {
          onClickEditStep('environment');
        }}
      >
        <BAIMetadataList columns="single">
          <MetadataListItem label={t('session.launcher.Project')}>
            {currentProject.name}
          </MetadataListItem>
          <MetadataListItem label={t('general.Image')}>
            <SessionLauncherImageRow />
          </MetadataListItem>
          {form.getFieldValue('envvars')?.length > 0 && (
            <MetadataListItem label={t('session.launcher.EnvironmentVariable')}>
              {form.getFieldValue('envvars')?.length ? (
                <SourceCodeView language={'shell'}>
                  {_.map(
                    form.getFieldValue('envvars'),
                    (v: { variable: string; value: string }) =>
                      `${v?.variable || ''}="${v?.value || ''}"`,
                  ).join('\n')}
                </SourceCodeView>
              ) : (
                <Text color="secondary">-</Text>
              )}
            </MetadataListItem>
          )}
        </BAIMetadataList>
      </BAICard>
      <BAICard
        title={t('session.launcher.ResourceAllocation')}
        showDivider
        status={
          _.some(form.getFieldValue('resource'), (_v, key) => {
            return (
              // @ts-ignore
              form.getFieldError(['resource', key]).length > 0
            );
          }) ||
          form.getFieldError(['num_of_sessions']).length > 0 ||
          form.getFieldError('resourceGroup').length > 0
            ? 'error'
            : undefined
        }
        size="small"
        extraButtonTitle={t('button.Edit')}
        onClickExtraButton={() => {
          onClickEditStep('environment');
        }}
      >
        <BAIFlex direction="column" align="stretch" gap="sm">
          {_.some(
            form.getFieldValue('resource'),
            (_v, key: keyof SessionLauncherFormValue['resource']) => {
              return (
                (form.getFieldWarning(['resource', key] as any) as any[])
                  .length > 0
              );
            },
          ) && (
            <Banner
              role="alert"
              status="warning"
              title={t('session.launcher.EnqueueComputeSessionWarning')}
            />
          )}
          {(form.getFieldWarning(['cluster_size'] as any) as any[]).length >
            0 && (
            <Banner
              role="alert"
              status="warning"
              title={
                (form.getFieldWarning(['cluster_size'] as any) as string[])[0]
              }
            />
          )}

          <BAIMetadataList columns={2}>
            <MetadataListItem label={t('general.ResourceGroup')}>
              {form.getFieldValue('resourceGroup') || (
                <Text color="secondary">{t('general.None')}</Text>
              )}
            </MetadataListItem>
            <MetadataListItem
              label={t('session.launcher.ResourceAllocationPerContainer')}
            >
              <BAIFlex
                direction="row"
                align="start"
                gap={'sm'}
                wrap="wrap"
                style={{ flex: 1 }}
              >
                {allocationMethodLabel ? (
                  <Token label={allocationMethodLabel} />
                ) : null}

                <ResourceNumbersOfSession
                  resource={form.getFieldValue('resource')}
                />
              </BAIFlex>
            </MetadataListItem>
            {!baiClient?._config?.hideAgents && (
              <MetadataListItem label={t('session.launcher.AgentNode')}>
                {_.castArray(form.getFieldValue('agent')).join(', ') ||
                  t('session.launcher.AutoSelect')}
              </MetadataListItem>
            )}
            <MetadataListItem label={t('session.launcher.NumberOfContainer')}>
              {form.getFieldValue('cluster_size') === 1
                ? form.getFieldValue('num_of_sessions')
                : form.getFieldValue('cluster_size')}
            </MetadataListItem>
            <MetadataListItem label={t('session.launcher.ClusterMode')}>
              {form.getFieldValue('cluster_mode') === 'single-node'
                ? t('session.launcher.SingleNode')
                : t('session.launcher.MultiNode')}
            </MetadataListItem>
          </BAIMetadataList>
          <Card padding={3}>
            <BAIFlex direction="column" align="stretch" gap="xs">
              <Heading level={6}>
                {t('session.launcher.TotalAllocation')}
              </Heading>
              <BAIFlex direction="row" gap="xxs" wrap="wrap">
                <ResourceNumbersOfSession
                  resource={form.getFieldValue('resource')}
                  containerCount={
                    form.getFieldValue('cluster_size') === 1
                      ? form.getFieldValue('num_of_sessions')
                      : form.getFieldValue('cluster_size')
                  }
                />
              </BAIFlex>
            </BAIFlex>
          </Card>
        </BAIFlex>
      </BAICard>
      <BAICard
        title={t('webui.menu.Data&Storage')}
        showDivider
        size="small"
        status={
          form.getFieldError('vfolderMounts').length > 0 ? 'error' : undefined
        }
        extraButtonTitle={t('button.Edit')}
        onClickExtraButton={() => {
          onClickEditStep('storage');
        }}
      >
        <BAIFlex direction="column" align="stretch" gap={'xs'}>
          {mountRows.length > 0 ? (
            <BAITable
              rowKey="vfolderId"
              size="small"
              pagination={false}
              columns={filterOutEmpty([
                {
                  dataIndex: 'name',
                  title: t('session.launcher.MountSourcePath'),
                  render: (
                    value: string,
                    record: (typeof mountRows)[number],
                  ) => (
                    <BAIFlex gap="xs" align="center">
                      <BAIVFolderIdenticon vfolderId={record.vfolderId} />
                      <BAILink to={generateFolderPath(record.vfolderId)}>
                        {value}
                      </BAILink>
                      {record.subpath ? (
                        <>
                          <Text color="secondary">/</Text>
                          {record.subpath}
                        </>
                      ) : null}
                    </BAIFlex>
                  ),
                },
                {
                  dataIndex: 'mountDestination',
                  title: t('session.launcher.MountDestinationPath'),
                  render: (
                    value: string,
                    record: (typeof mountRows)[number],
                  ) =>
                    record.isDefaultAlias ? (
                      <Text color="placeholder">{value}</Text>
                    ) : (
                      value
                    ),
                },
              ])}
              dataSource={mountRows}
            />
          ) : (
            <Banner
              role="alert"
              status="warning"
              title={t('session.launcher.NoFolderMounted')}
            />
          )}
          {autoMountedFolders.length > 0 ? (
            <BAIMetadataList columns="single">
              <MetadataListItem label={t('data.AutomountFolders')}>
                <BAIFlex gap="xs" wrap="wrap">
                  {_.map(autoMountedFolders, (folder) => (
                    <BAILink
                      key={folder.vfolderId}
                      to={generateFolderPath(folder.vfolderId)}
                    >
                      <Token label={folder.name} />
                    </BAILink>
                  ))}
                </BAIFlex>
              </MetadataListItem>
            </BAIMetadataList>
          ) : null}
        </BAIFlex>
      </BAICard>
      <BAICard
        title={t('session.launcher.Network')}
        showDivider
        size="small"
        status={form.getFieldError('ports').length > 0 ? 'error' : undefined}
        extraButtonTitle={t('button.Edit')}
        onClickExtraButton={() => {
          onClickEditStep('network');
        }}
      >
        <BAIMetadataList columns="single">
          <MetadataListItem label={t('session.launcher.PreOpenPortTitle')}>
            <BAIFlex direction="row" gap="xs" style={{ flex: 1 }} wrap="wrap">
              {_.sortBy(form.getFieldValue('ports'), (v) => parseInt(v)).map(
                (v, idx) => (
                  <PortToken key={idx + v} value={v} style={{ margin: 0 }}>
                    {v}
                  </PortToken>
                ),
              )}

              {!_.isArray(form.getFieldValue('ports')) ||
              form.getFieldValue('ports')?.length === 0 ? (
                <Text color="secondary">{t('general.None')}</Text>
              ) : null}
            </BAIFlex>
          </MetadataListItem>
        </BAIMetadataList>
      </BAICard>
    </>
  );
};

export default SessionLauncherPreview;
